const RS=ReaderStore.create((()=>{try{const ls=window.localStorage;ls.getItem('hcp:probe');return ls;}catch{const m={};return {getItem:k=>k in m?m[k]:null,setItem:(k,v)=>{m[k]=String(v);},removeItem:k=>{delete m[k];}};}})(),location.search,{onWiped:()=>{try{location.reload();}catch{}}});
