let pref={lang:'id',size:18,night:false,mode:'paged',sepia:false,motion:true,layoutVersion:14},s=E.fresh(),storageOK=true,returnFocus=null,jtab='choices',choiceBusy=false;
try{const p=JSON.parse(RS.get('nadira-bilingual-prefs')||RS.deviceGet('hcp:last-lang'));if(p){if(['id','zh'].includes(p.lang))pref.lang=p.lang;if([16,18,20,22].includes(p.size))pref.size=p.size;pref.night=!!p.night;pref.sepia=!!p.sepia;pref.motion=p.motion!==false;if(p.layoutVersion===14&&['scroll','paged'].includes(p.mode))pref.mode=p.mode;}EPISODES=storyLanguage(pref.lang);s=E.restore(JSON.parse(RS.get(E.KEY)),EPISODES);}catch{}RS.adopt();const JUST_RESET=/^#reset/.test(location.hash);if(JUST_RESET){s.view='cover';try{history.replaceState(null,'',location.pathname+location.search);}catch{}}
