const ENDINGS=[['A','Pulang ke Aku|回到我身边','Rute Arya|Arya线'],['R','Rumah yang Sama, Pintu yang Baru|同一个家，一扇新的门','Rute Raka|Raka线'],['S','Panggungku Sendiri|我自己的舞台','Rute solo|独立线'],['X','💎 Pesan Jam 02.13|💎 凌晨2:13的消息','Ending rahasia|隐藏结局']];
function endingsSeen(){try{return JSON.parse(RS.get('nadira-endings-v20'))||[];}catch{return [];}}
function recordEnding(){const id=E.endingOf(s),seen=endingsSeen();if(!seen.includes(id)){seen.push(id);RS.set('nadira-endings-v20',JSON.stringify(seen));}}
function endingsHtml(){const seen=endingsSeen(),cur=s.finished?E.endingOf(s):null;return `<div class="endings-gallery">${ENDINGS.map(([id,name,route])=>`<div class="ending-slot ${seen.includes(id)?'open':'locked'} ${cur===id?'current':''}"><small>${esc(L(route)[pref.lang])}</small><strong>${seen.includes(id)?esc(L(name)[pref.lang]):'? ? ?'}</strong>${seen.includes(id)?'':`<em>${id==='X'?t('Petunjuk: buka satu pesan sebelum memilih siapa pun.','提示：在选择任何人之前，先打开一条消息。'):t('Petunjuk: pintu lain di bab 18.','提示：第18集的另一扇门。')}</em>`}</div>`).join('')}</div>`;}
function endingsGallery(){openModal(t('GALERI ENDING','结局图鉴'),`${endingsSeen().length}/4 ${t('ending terbuka','个结局已解锁')}`,`${endingsHtml()}<button class="primary" data-action="review" data-index="17" data-key="reconcile"><span>${t('Ulangi dari Bab 18 · tiga pintu','从第18集“三扇门”重玩')}</span><span>→</span></button>`);}

modal.addEventListener('cancel',ev=>{ev.preventDefault();closeModal();});
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeModal();}});
render();

// Restore the current reading position without changing story choices.
let positionTimer;
function savePosition(){if(s.view!=='reader'||pref.mode!=='scroll'||modal.open)return;RS.set('nadira-reader-position-v13',JSON.stringify({ep:s.ep,step:s.step,y:window.scrollY}));}
window.addEventListener('scroll',()=>{clearTimeout(positionTimer);positionTimer=setTimeout(savePosition,150);},{passive:true});
window.addEventListener('pagehide',savePosition);
// v22: reader-test abandon points. A 'leave' with no later 'return' in the same session is where the reader quit.
track('session_start',{tester:TESTER||null,view:s.view,ep:s.ep,step:s.step,returning:RA.events().some(e=>e.type==='panel'),w:innerWidth,h:innerHeight});
function leaveLog(reason){if(hiddenAt)return;hiddenAt=Date.now();track('leave',{reason,view:s.view,ep:s.ep,step:s.step,page:s.page,idx:s.step*100+s.page,modal:modal.open?(phoneScreen?.type||'modal'):null,onPanelMs:Date.now()-panelAt});}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')leaveLog('hidden');else if(hiddenAt){track('return',{awayMs:Date.now()-hiddenAt,ep:s.ep});panelAt+=Date.now()-hiddenAt;hiddenAt=0;}});
window.addEventListener('pagehide',()=>leaveLog('pagehide'));
try{const pos=JSON.parse(RS.get('nadira-reader-position-v13'));if(s.view==='reader'&&pref.mode==='scroll'&&pos?.ep===s.ep&&pos?.step===s.step&&Number.isFinite(pos.y))requestAnimationFrame(()=>window.scrollTo({top:pos.y,behavior:'instant'}));else if(s.view==='reader'&&pref.mode==='scroll'&&s.step>0)requestAnimationFrame(()=>document.querySelector(`[data-beat="${s.step%2===0?s.step-1:s.step}"]`)?.scrollIntoView({block:'start',behavior:'instant'}));}catch{}
